import atexit
import os
import sys
import zlib
from io import BytesIO, StringIO
from tempfile import TemporaryFile

# ! Deunder

__all__ = ['ICON', 'get_icon_path']

# ! Variables

_TEMPORARY_FILE_PATHS = []

# ! Functions

def _cleanup():
    for filepath in _TEMPORARY_FILE_PATHS:
        try:
            os.remove(filepath)
        except:  # noqa: E722, S110
            pass

def _hex_to_bytes(src: str, /) -> bytes:
    if len(src) % 2 != 0:
        raise ValueError("The value must consist of two-digit HEX numbers.")
    with BytesIO() as bio:
        with StringIO(src) as sio:
            while len(hex_byte := sio.read(2)) > 0:
                bio.write(int(hex_byte, base=16).to_bytes())
        result = bio.getvalue()
    return result

def get_icon_path() -> str:
    with TemporaryFile('wb', suffix='.ico', delete=False, delete_on_close=False) as tmpfile:
        filepath = tmpfile.name
        tmpfile.write(zlib.decompress(_hex_to_bytes(ICON)))
    _TEMPORARY_FILE_PATHS.append(filepath)
    return filepath

def _exception_handler(exctype, value, traceback):
    _cleanup()
    sys.__excepthook__(exctype, value, traceback)

atexit.register(_cleanup)
sys.excepthook = _exception_handler

